import map from "./map-data.json";

// Oblasts (outlines and labels) and raions (filled by alert status), generated by scripts/build-map.mjs.
// Ids are the names used by the alerts APIs: "Вінницька область", "Вінницький район", "м. Київ".
export type Shape = { id: string; d: string; x: number; y: number };
export const VIEW_BOX: string = map.viewBox;
export const OBLASTS: (Shape & { label: string })[] = map.oblasts;
export const RAIONS: (Shape & { oblast: string })[] = map.raions;

// red: alert, partial: alert only in some hromadas of the raion, yellow: preliminary threat
export type Status = "red" | "partial" | "yellow" | "none";

export type AlertsData = {
  source: "alerts.in.ua" | "ubilling";
  updatedAt: string;
  // raion id -> status
  raions: Record<string, Status>;
  // raion or oblast id -> threat types (drones, cruise_missiles...)
  threats: Record<string, string[]>;
};
